// Card grid for the draw (shuffle) animation, as CSS custom properties.
// Up to 12 cards keep the original 4-column layout; larger groups (up to 24) use
// 6 smaller columns so every row stays on screen (see .deck.many in Integration.css).
export const MANY_CARDS = 12;
export function cardPosition(i, count) {
  if (count <= MANY_CARDS)
    return {
      "--sx": (i % 4) - 1.5,
      "--sy": Math.floor(i / 4) - 1,
      "--ex": (i % 4) - 1.8,
      "--ey": Math.floor(i / 4) - 1,
    };
  const cols = 6,
    rows = Math.ceil(count / cols),
    x = (i % cols) - (cols - 1) / 2,
    y = Math.floor(i / cols) - (rows - 1) / 2;
  return { "--sx": x, "--sy": y, "--ex": x - 0.3, "--ey": y };
}
