// Presentation helpers for the current group-competition (fruit) match.
// Pure functions over the room state; no React, no room commands.
import * as engine from "./fruitEngine";
import fruits from "./fruits.json";

const fruitName = (id) => fruits.find((f) => f.slug === id)?.name_zh || id;
// Team name from its two fruits, in the fixed fruit-list order so it never changes
// when players swap positions: ["guava", "banana"] -> "香蕉芭樂隊".
export function teamName(ids) {
  if (!ids?.length) return null;
  const order = (id) => engine.FRUIT_IDS.indexOf(id);
  return `${[...ids]
    .sort((a, b) => order(a) - order(b))
    .map(fruitName)
    .join("")}隊`;
}

// Label for the red (A) / blue (B) side: the fruit team name in group competition
// (the lineup is that match's resolved team), "隊伍 A/B" in normal mode.
export function sideLabel(state, side) {
  const ids = state?.activityMode === "fruit" ? state.lineup?.[side] : null;
  return (ids?.length === 2 && teamName(ids)) || `隊伍 ${side}`;
}

// Whether the pending match still needs its 7-player borrow chosen. Once the
// borrow is stored (even via a retried request) the picker must not offer it again.
export function borrowNeeded(pending) {
  if (!pending || pending.i < 0) return false;
  const m = pending.r.matches[pending.i];
  return !engine.team(pending.r, m.a) || !engine.team(pending.r, m.b);
}

// Roster edits that will be applied to the active round when the next match loads.
export function rosterChanged(fruit) {
  const r = fruit && engine.activeRound(fruit);
  if (!r) return false;
  const now = fruit.selected;
  return (
    now.length !== r.roster.length || now.some((id) => !r.roster.includes(id))
  );
}

// "第 2 場後：加入 香蕉、芭樂；離開 西瓜" for a round whose roster changed mid-way.
export function amendNotice(round) {
  const a = round?.amended;
  if (!a || (!a.joined.length && !a.left.length)) return null;
  const names = (ids) => ids.map(fruitName).join("、");
  const parts = [];
  if (a.joined.length) parts.push(`加入 ${names(a.joined)}`);
  if (a.left.length) parts.push(`離開 ${names(a.left)}`);
  return `第 ${a.afterMatch} 場後：${parts.join("；")}`;
}
