// Spoken variants the recognizer commonly returns for each part of a command.
// Add new homophones / accent variants here only; commands.js builds its matcher from this table.
const ALIASES = {
  red: ["紅", "洪", "宏", "鴻", "虹"],
  // Taiwanese Mandarin often merges l/n, so 藍 is frequently heard as 南/男.
  blue: ["藍", "南", "男", "蘭", "嵐", "籃"],
  side: ["方", "隊", "邊", "色", "坊", "芳"],
  plus: ["加", "家", "佳", "\\+"],
  one: ["一", "1", "衣", "依"],
  // Whole-phrase alternatives that score one point without "加一".
  score: ["得分", "得一分", "得1分"],
  undo: ["加錯分數", "加錯分樹", "加錯分", "家錯分數", "佳錯分數", "加錯分術"],
};
// Separators the recognizer inserts inside an utterance ("紅方，加一").
const INNER_PUNCTUATION = /[，、,·]/gu;

module.exports = { ALIASES, INNER_PUNCTUATION };
