import { useCallback, useEffect, useRef, useState } from "react";
import * as model from "./roomModel";
import * as fruit from "./fruitEngine";
const RECENT = "synscore-recent-room-v2",
  LOCAL = "synscore-local-room-v2",
  ACTIVE = "synscore-active-room-v2",
  PENDING = "synscore-pending-command-v2";
const TTL = 7200000;
const production =
  typeof window !== "undefined" &&
  window.location.hostname === "shawn-2007.github.io";
export const API =
  process.env.REACT_APP_API_BASE ??
  (production ? "https://api.shawn4x4.com/nodeApi" : "");
const WS =
  process.env.REACT_APP_WS_BASE ||
  (production
    ? "wss://api.shawn4x4.com/ws/"
    : `${window.location.protocol === "https:" ? "wss:" : "ws:"}//${window.location.host}/ws/`);
function load(key) {
  try {
    return JSON.parse(localStorage.getItem(key));
  } catch {
    return null;
  }
}
function save(key, value) {
  try {
    if (value === null) localStorage.removeItem(key);
    else localStorage.setItem(key, JSON.stringify(value));
  } catch {}
}
function clearPending(key, id) {
  if (load(key)?.operationId === id) save(key, null);
}
function saveActive(ref) {
  try {
    if (ref) sessionStorage.setItem(ACTIVE, JSON.stringify(ref));
    else sessionStorage.removeItem(ACTIVE);
  } catch {}
}
export function clearActiveRoom() {
  saveActive(null);
}
export function activeRoom() {
  try {
    const ref = JSON.parse(sessionStorage.getItem(ACTIVE));
    return ref?.kind === "online" && /^\d{5}$/.test(ref.roomKey) && ref.roomId
      ? ref
      : null;
  } catch {
    return null;
  }
}
export function recentRoom() {
  const r = load(RECENT);
  return r &&
    Number.isFinite(r.enteredAt) &&
    r.enteredAt <= Date.now() + 60000 &&
    Date.now() - r.enteredAt < TTL
    ? r
    : null;
}
async function json(url, body) {
  const controller = new AbortController(),
    timer = setTimeout(() => controller.abort(), 15000);
  try {
    const response = await fetch(API + url, {
      signal: controller.signal,
      ...(body === undefined
        ? {}
        : {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
          }),
    });
    const data = await response.json();
    if (!response.ok) {
      const e = new Error(data.error || "連線失敗");
      e.status = response.status;
      e.state = data.state;
      throw e;
    }
    return data;
  } finally {
    clearTimeout(timer);
  }
}
function localRoom() {
  const saved = load(LOCAL);
  if (saved?.schemaVersion === 2 && saved.game?.history && saved.fruit?.rounds)
    return saved;
  const room = model.freshRoom("local");
  const old = load("synscore-local-game");
  if (old && Array.isArray(old.history)) {
    room.game = { ...room.game, ...old, targetPoints: old.targetPoints || 21 };
    if (typeof old.flipA !== "boolean") {
      let a = false,
        b = false;
      room.game.history.forEach((before, i) => {
        before.flipA = a;
        before.flipB = b;
        const after = old.history[i + 1] || old;
        const scorer = after.teamAScore > before.teamAScore ? "A" : "B";
        if (scorer === before.servingTeam) {
          if (scorer === "A") a = !a;
          else b = !b;
        }
      });
      room.game.flipA = a;
      room.game.flipB = b;
    }
    room.records = (old.results || []).map((r, i) => ({
      ...r,
      id: `legacy-${r.endedAt}-${i}`,
      roomId: room.roomId,
      roomKey: "local",
      day: model.dayKey(r.endedAt),
      status: "done",
      revision: 1,
      teamA: [],
      teamB: [],
    }));
  }
  return room;
}
export default function useSynRoom() {
  const [state, setState] = useState(null),
    [session, setSession] = useState(null),
    [status, setStatus] = useState("idle"),
    [busy, setBusy] = useState(false),
    [error, setError] = useState(""),
    [pending, setPending] = useState(null);
  const current = useRef(null),
    raw = useRef(null),
    lock = useRef(false),
    generation = useRef(0),
    createId = useRef(null),
    pendingRef = useRef(null);
  const apply = useCallback((data) => {
    if (
      current.current &&
      data.roomId === current.current.roomId &&
      data.version < current.current.version
    )
      return;
    current.current = data;
    setState(data);
  }, []);
  const join = useCallback(
    async (key, expectedId, enteredAt) => {
      setError("");
      setStatus("connecting");
      const gen = ++generation.current;
      pendingRef.current = null;
      setPending(null);
      lock.current = false;
      setBusy(false);
      try {
        const data = await json(
          `/api/room-state?room=${encodeURIComponent(key)}&protocol=2${expectedId ? "&roomId=" + encodeURIComponent(expectedId) : ""}`,
        );
        if (gen !== generation.current) return false;
        current.current = null;
        apply(data);
        const ref = {
          kind: "online",
          roomKey: key,
          roomId: data.roomId,
          enteredAt: enteredAt || Date.now(),
        };
        save(RECENT, ref);
        saveActive(ref);
        setSession(ref);
        return true;
      } catch (e) {
        if (gen !== generation.current) return false;
        setError(e.message);
        setStatus("offline");
        if (e.status === 404 || e.status === 410) {
          save(RECENT, null);
          saveActive(null);
        }
        return false;
      }
    },
    [apply],
  );
  const create = async () => {
    if (lock.current) return false;
    const gen = generation.current;
    lock.current = true;
    setBusy(true);
    setError("");
    try {
      createId.current ||= crypto.randomUUID();
      const data = await json("/api/create-room", {
        operationId: createId.current,
      });
      if (gen !== generation.current) return false;
      createId.current = null;
      return await join(data.roomKey, data.roomId);
    } catch (e) {
      if (gen === generation.current) setError(e.message);
      return false;
    } finally {
      if (gen === generation.current) {
        lock.current = false;
        setBusy(false);
      }
    }
  };
  const single = (enteredAt = Date.now()) => {
    saveActive(null);
    ++generation.current;
    lock.current = false;
    setBusy(false);
    pendingRef.current = null;
    setPending(null);
    raw.current = localRoom();
    save(LOCAL, raw.current);
    current.current = null;
    apply(model.view(raw.current));
    const ref = {
      kind: "local",
      roomKey: "local",
      roomId: raw.current.roomId,
      enteredAt,
    };
    save(RECENT, ref);
    setSession(ref);
    setStatus("local");
    setError("");
  };
  const resume = async (ref = recentRoom()) => {
    if (!ref) return false;
    if (ref.kind === "local") {
      single(ref.enteredAt);
      return true;
    }
    return join(ref.roomKey, ref.roomId, ref.enteredAt);
  };
  const transmit = useCallback(
    async (body) => {
      if (lock.current) return null;
      const gen = generation.current;
      lock.current = true;
      setBusy(true);
      setError("");
      const key = PENDING + ":" + body.roomId;
      pendingRef.current = body;
      setPending(body);
      save(key, body);
      try {
        const result = await json("/api/command", body);
        clearPending(key, body.operationId);
        if (
          gen !== generation.current ||
          current.current?.roomId !== body.roomId
        )
          return null;
        apply(result);
        pendingRef.current = null;
        setPending(null);
        return result;
      } catch (e) {
        if (e.status && e.status < 500) clearPending(key, body.operationId);
        if (
          gen !== generation.current ||
          current.current?.roomId !== body.roomId
        )
          return null;
        if (e.state) apply(e.state);
        if (e.status && e.status < 500) {
          pendingRef.current = null;
          setPending(null);
        }
        setError(
          e.status
            ? e.message
            : "連線中斷，操作結果尚未確認。請重送同一筆操作。",
        );
        return null;
      } finally {
        if (gen === generation.current) {
          lock.current = false;
          setBusy(false);
        }
      }
    },
    [apply],
  );
  useEffect(() => {
    if (session?.kind !== "online") return;
    let closed = false,
      ws,
      timer,
      attempt = 0;
    const stored = load(PENDING + ":" + session.roomId);
    if (stored?.roomId === session.roomId) {
      pendingRef.current = stored;
      setPending(stored);
    } else {
      pendingRef.current = null;
      setPending(null);
    }
    const connect = () => {
      if (!navigator.onLine) {
        setStatus("offline");
        return;
      }
      setStatus("connecting");
      ws = new WebSocket(
        `${WS}?room=${session.roomKey}&roomId=${session.roomId}&protocol=2`,
      );
      ws.onopen = () => {
        attempt = 0;
      };
      ws.onmessage = (e) => {
        if (closed) return;
        try {
          const data = JSON.parse(e.data);
          if (data.roomId !== session.roomId) return;
          apply(data);
          setStatus("online");
          if (pendingRef.current && !lock.current) transmit(pendingRef.current);
        } catch {
          setError("收到無法辨識的同步訊息。");
        }
      };
      ws.onclose = (e) => {
        if (closed) return;
        if (e.code === 4404 || e.code === 4409) {
          setStatus("expired");
          setError("房間已失效或需要新版計分板。");
          save(RECENT, null);
          saveActive(null);
          return;
        }
        setStatus("offline");
        timer = setTimeout(connect, Math.min(2000 * 2 ** attempt++, 10000));
      };
      ws.onerror = () => {};
    };
    connect();
    const visible = () => {
      if (
        document.visibilityState === "visible" &&
        (!ws || ws.readyState > 1)
      ) {
        clearTimeout(timer);
        connect();
      }
    };
    const offline = () => {
      setStatus("offline");
      clearTimeout(timer);
      ws?.close();
    };
    window.addEventListener("online", visible);
    window.addEventListener("offline", offline);
    document.addEventListener("visibilitychange", visible);
    return () => {
      closed = true;
      clearTimeout(timer);
      document.removeEventListener("visibilitychange", visible);
      window.removeEventListener("online", visible);
      window.removeEventListener("offline", offline);
      ws?.close();
    };
  }, [session, apply, transmit]);
  const act = async (action, payload = {}) => {
    if (lock.current || pendingRef.current || !current.current) return null;
    if (session?.kind === "online" && status !== "online") {
      setError("請等待重新連線後再操作。");
      return null;
    }
    const s = current.current;
    const body = {
      roomKey: s.roomKey,
      roomId: s.roomId,
      operationId: crypto.randomUUID(),
      expectedVersion: s.version,
      matchId: s.matchId,
      roundId: fruit.activeRound(s.fruit)?.id || null,
      action,
      payload,
    };
    if (session?.kind === "local") {
      try {
        raw.current = model.applyCommand(raw.current, body);
        save(LOCAL, raw.current);
        const result = model.view(raw.current);
        apply(result);
        setError("");
        return result;
      } catch (e) {
        setError(e.message);
        return null;
      }
    }
    return transmit(body);
  };
  const archived = async (roomId) => {
    try {
      return (await json("/api/results?roomId=" + encodeURIComponent(roomId)))
        .records;
    } catch (e) {
      setError(e.message);
      return [];
    }
  };
  return {
    state,
    session,
    status,
    busy,
    error,
    setError,
    create,
    join,
    single,
    resume,
    act,
    pending,
    retry: () => pendingRef.current && transmit(pendingRef.current),
    archived,
  };
}
