// Bring a device that sits on the draw / schedule / records page back to the live match.
// Rule (approved 2026-10-10): when another device scores while this one is away and this
// device has been idle for 10 s, return to the scoreboard; a bar on those pages shows the
// live score and returns on tap. Someone actively editing (e.g. the next roster) is never
// pulled away mid-edit.
import React, { useEffect, useRef } from "react";

export const AWAY_PAGES = ["draw", "schedule", "stats"];
export const IDLE_MS = 10000;

// A match is live once someone has scored and nobody has won yet.
export function isLive(s) {
  return (
    !!s &&
    s.matchPhase === "playing" &&
    !s.winner &&
    s.teamAScore + s.teamBScore > 0
  );
}

export function shouldReturn({
  page,
  live,
  scoredWhileAway,
  idleFor,
  idleMs = IDLE_MS,
}) {
  return (
    AWAY_PAGES.includes(page) && live && scoredWhileAway && idleFor >= idleMs
  );
}

export function useLiveMatchFollow({
  state,
  page,
  onReturn,
  idleMs = IDLE_MS,
}) {
  const lastInput = useRef(Date.now()),
    scored = useRef(false),
    seenScore = useRef(null),
    timer = useRef(null),
    latest = useRef({ state, onReturn });
  latest.current = { state, onReturn };

  useEffect(() => {
    const mark = () => {
      lastInput.current = Date.now();
    };
    const events = ["pointerdown", "keydown", "wheel", "touchstart"];
    events.forEach((e) => window.addEventListener(e, mark, { passive: true }));
    return () => events.forEach((e) => window.removeEventListener(e, mark));
  }, []);

  useEffect(() => {
    scored.current = false;
    lastInput.current = Date.now();
  }, [page]);

  const scoreKey = state
    ? `${state.matchId}:${state.teamAScore}:${state.teamBScore}`
    : "";
  useEffect(() => {
    if (
      seenScore.current !== null &&
      scoreKey !== seenScore.current &&
      AWAY_PAGES.includes(page)
    )
      scored.current = true;
    seenScore.current = scoreKey;
  }, [scoreKey, page]);

  useEffect(() => {
    clearTimeout(timer.current);
    if (!AWAY_PAGES.includes(page) || !scored.current) return;
    const check = () => {
      const idleFor = Date.now() - lastInput.current;
      if (
        shouldReturn({
          page,
          live: isLive(latest.current.state),
          scoredWhileAway: scored.current,
          idleFor,
          idleMs,
        })
      )
        latest.current.onReturn();
      else if (isLive(latest.current.state))
        timer.current = setTimeout(check, Math.max(500, idleMs - idleFor));
    };
    check();
    return () => clearTimeout(timer.current);
  }, [scoreKey, page, idleMs]);
}

export function LiveMatchBar({ state, page, labels, onOpen }) {
  if (!AWAY_PAGES.includes(page) || !isLive(state)) return null;
  return (
    <button className="live-match-bar" onClick={onOpen}>
      <span className="live-dot" aria-hidden="true" />
      比賽進行中　{labels[0]} <b>{state.teamAScore}</b> :{" "}
      <b>{state.teamBScore}</b> {labels[1]}
      <span className="live-go">回計分頁 →</span>
    </button>
  );
}
