const { ALIASES, INNER_PUNCTUATION } = require("./aliases");

const any = (list) => `(?:${list.join("|")})`;
const POINT = new RegExp(
  `^(${any(ALIASES.red)}|${any(ALIASES.blue)})${any(ALIASES.side)}` +
    `(?:${any(ALIASES.plus)}${any(ALIASES.one)}(?:分)?|${any(ALIASES.score)})$`,
  "u",
);
const UNDO = new Set(ALIASES.undo);

// Deliberately accept one complete command, never substring matches or guesses.
// Spoken variants come from aliases.js; the structure (team + side + "加一") stays strict.
function parseCommand(raw) {
  const normalized = String(raw || "")
    .normalize("NFKC")
    .replace(/\s+/g, "")
    .replace(INNER_PUNCTUATION, "")
    .replace(/[。.!！]+$/u, "");
  let command = null;
  if (UNDO.has(normalized)) {
    command = { key: "undo", action: "undo", payload: {} };
  } else {
    const match = POINT.exec(normalized);
    if (match) {
      const team = ALIASES.red.includes(match[1]) ? "A" : "B";
      command = { key: `point:${team}`, action: "point", payload: { team } };
    }
  }
  return { normalized, command };
}
module.exports = { parseCommand };
