// Mid-round roster changes for group competition, applied when the next match is loaded.
// Pure and deterministic: a client can preview exactly what the server will do.
// Rules (approved 2026-10-10):
// - Existing teams are kept. A leaver is replaced by the resting player (or a newcomer)
//   when there is one; otherwise their partner rests and that team leaves the round.
// - Newcomers pair with the resting player first, then with each other; one left over rests.
// - If the finished matches are the start of the normal schedule for the new team count,
//   continue with it (8 -> 10 players: A-B, C-D, then E-A, B-C, D-E).
// - Otherwise plan the rest: fewest games first, no rematches, avoid back-to-back, until
//   every team reaches its target (2 games full, 1 quick).
// - A 7-player borrow round becomes a normal round (the borrow team is dropped).
// - Fewer than 4 players: the round continues unchanged; the roster applies next round.
const F = require("./fruitEngine");

const LETTERS = Array.from({ length: 26 }, (_, i) =>
  String.fromCharCode(65 + i),
);
const sameSet = (a, b) =>
  a.length === b.length && a.every((x) => b.includes(x));
const pairKey = (x, y) => [x, y].sort().join("|");

// W0/L1 style references resolved to the team letter that actually played.
function baseKey(r, ref) {
  const m = /^([WL])(\d+)$/.exec(ref);
  if (!m) return ref;
  const g = r.matches[Number(m[2])];
  if (!g?.score) return null;
  const firstWon = g.score[0] > g.score[1];
  return baseKey(r, (m[1] === "W") === firstWon ? g.a : g.b);
}

function targetGames(k, mode) {
  if (k <= 2) return 1;
  return mode === "quick" && k >= 4 ? 1 : 2;
}

function planRemaining(letters, played, target) {
  const games = Object.fromEntries(letters.map((t) => [t, 0]));
  const met = new Set();
  for (const [x, y] of played) {
    if (x in games) games[x]++;
    if (y in games) games[y]++;
    met.add(pairKey(x, y));
  }
  let last = played.at(-1) || [];
  const plan = [];
  for (let guard = 0; guard < 64; guard++) {
    const need = letters.filter((t) => games[t] < target);
    if (!need.length) break;
    // A single team still short plays someone who already has enough (like W0).
    const pool = need.length >= 2 ? need : letters;
    let best = null;
    for (const x of need)
      for (const y of pool) {
        if (x === y) continue;
        const cost =
          (met.has(pairKey(x, y)) ? 100 : 0) +
          (last.includes(x) || last.includes(y) ? 10 : 0) +
          games[x] +
          games[y];
        if (!best || cost < best.cost) best = { x, y, cost };
      }
    if (!best) break;
    plan.push([best.x, best.y]);
    games[best.x]++;
    games[best.y]++;
    met.add(pairKey(best.x, best.y));
    last = [best.x, best.y];
  }
  return plan;
}

function amendRound(s) {
  const r = F.activeRound(s);
  if (!r || sameSet(s.selected, r.roster)) return s;
  const target = s.selected;
  if (target.length < 4 || target.length > F.MAX_PLAYERS) return s;
  const out = structuredClone(s),
    round = F.activeRound(out);
  const done = round.matches.filter((m) => m.status === "done");
  for (const m of done) m.lineup ||= F.matchTeams(round, m).map((t) => [...t]);
  const played = done.map((m) => [baseKey(round, m.a), baseKey(round, m.b)]);
  const wasBorrow = round.seven === "borrow";

  const teams = {};
  let singles = round.rest ? [round.rest] : [];
  for (const [k, ids] of Object.entries(round.teams)) {
    if (k === "補位隊") continue; // derived from W0, rebuilt by the schedule
    if (ids.length === 2) teams[k] = [...ids];
    else singles.push(...ids);
  }
  const before = Object.keys(teams).sort().join();
  const present = [...Object.values(teams).flat(), ...singles];
  const leavers = present.filter((p) => !target.includes(p));
  const joiners = target.filter((p) => !present.includes(p));
  singles = [...singles, ...joiners].filter((p) => !leavers.includes(p));
  for (const p of leavers) {
    const k = Object.keys(teams).find((t) => teams[t].includes(p));
    if (!k) continue; // was resting or the borrow single
    const partner = teams[k].find((x) => x !== p);
    if (singles.length) teams[k] = [partner, singles.shift()];
    else {
      delete teams[k];
      singles.push(partner);
    }
  }
  const used = new Set([...Object.keys(teams), ...played.flat()]);
  while (singles.length >= 2) {
    const k = LETTERS.find((l) => !used.has(l));
    used.add(k);
    teams[k] = [singles.shift(), singles.shift()];
  }
  const rest = singles[0] || null;
  const letters = Object.keys(teams).sort();

  let pending;
  if (!wasBorrow && letters.join() === before)
    pending = round.matches.filter((m) => m.status === "pending");
  else {
    const k = letters.length,
      rule = F.fixturesFor(k, round.mode);
    const continues =
      letters.join() === LETTERS.slice(0, k).join() &&
      done.length < rule.length &&
      done.every((m, i) => m.a === rule[i][0] && m.b === rule[i][1]);
    const plan = continues
      ? rule.slice(done.length)
      : planRemaining(letters, played, targetGames(k, round.mode));
    pending = plan.map(([a, b]) => ({ a, b, status: "pending" }));
  }

  round.teams = teams;
  round.rest = rest;
  round.roster = [...target];
  if (wasBorrow) round.seven = "rest";
  if (rest && rest !== r.rest && !out.restSeen.includes(rest))
    out.restSeen.push(rest);
  round.matches = [...done, ...pending];
  round.amended = {
    afterMatch: done.length,
    joined: joiners,
    left: leavers,
  };
  if (!pending.length) round.status = "complete";
  return out;
}

module.exports = { amendRound, planRemaining };
