import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createVoiceController } from "./controller";

const PREFERENCE = "synscore-voice-scoring";
// Pages inside a room's match flow: moving between them only pauses listening.
const MATCH_PAGES = ["board", "victory", "schedule", "draw", "stats"];
function preference() {
  try {
    return localStorage.getItem(PREFERENCE) === "on";
  } catch {
    return false;
  }
}
export default function useVoiceScoring({
  page,
  room,
  available,
  modal,
  onActivate,
}) {
  const [enabled, setEnabled] = useState(preference);
  const [status, setStatus] = useState({
    phase: "stopped",
    message: "尚未收音",
  });
  const [logs, setLogs] = useState([]);
  const alive = useRef(true),
    entries = useRef([]),
    serial = useRef(0),
    exported = useRef(null);
  const latest = useRef(null),
    controller = useRef(null);
  const s = room.state;
  const connected = ["online", "local"].includes(room.status);
  const scope = `${room.session?.kind}:${s?.roomId}:${s?.matchId}`;
  const inPlay = !!s?.isGameStarted && !s?.winner && s?.matchPhase !== "ready";
  const active = page === "board" && !!s;
  const blockedReason = !active
    ? "outside-scoreboard"
    : !inPlay
      ? "match-not-playing"
      : !connected
        ? "offline"
        : modal
          ? "dialog-open"
          : !available
            ? "command-or-animation-busy"
            : null;
  latest.current = {
    scope,
    active,
    inPlay,
    connected,
    available: !!available && !modal,
    canStart: !!available && active && inPlay,
    blockedReason,
    canUndo: !!s?.canUndo,
    roomId: s?.roomId,
    matchId: s?.matchId,
    act: room.act,
  };
  const Recognition =
    window.SpeechRecognition || window.webkitSpeechRecognition;
  const supported = !!Recognition && window.isSecureContext;
  if (!controller.current) {
    controller.current = createVoiceController({
      createRecognition: () => {
        const Native =
          window.SpeechRecognition || window.webkitSpeechRecognition;
        if (!Native || !window.isSecureContext)
          throw new Error("Speech recognition unavailable");
        return new Native();
      },
      getContext: () => ({
        ...latest.current,
        visible: document.visibilityState === "visible",
      }),
      send: (command) => latest.current.act(command.action, command.payload),
      log: (entry) => {
        if (!alive.current) return;
        const row = {
          id: ++serial.current,
          at: new Date().toISOString(),
          ...entry,
        };
        entries.current = [...entries.current.slice(-299), row];
        setLogs(entries.current);
      },
      state: (update) => {
        if (alive.current)
          setStatus((previous) => ({ ...previous, ...update }));
      },
    });
  }
  const sessionKey = `${room.session?.kind}:${room.session?.roomId}`;
  const inMatchFlow = MATCH_PAGES.includes(page);
  useLayoutEffect(() => {
    // A different room or leaving the room's pages needs a new explicit start.
    controller.current.stop("room-or-session-changed");
  }, [sessionKey]);
  useLayoutEffect(() => {
    if (!inMatchFlow) controller.current.stop("left-match-pages");
  }, [inMatchFlow]);
  useLayoutEffect(() => {
    // Match change, winner, victory page or reconnect: pause, then resume automatically.
    controller.current.suspend("match-page-or-connection-changed");
  }, [scope, active, inPlay, connected]);
  useLayoutEffect(() => {
    if (!available || modal)
      controller.current.invalidate(blockedReason || "not-writable");
    if (modal) controller.current.suspend("dialog-open");
  }, [available, modal, blockedReason]);
  useEffect(() => {
    // Resume an armed (paused) session once scoring is possible again.
    if (active && inPlay && connected && available && !modal)
      controller.current.wake();
  }, [scope, active, inPlay, connected, available, modal]);
  useEffect(() => {
    alive.current = true;
    const visibility = () => {
      if (document.visibilityState !== "visible")
        controller.current.stop("background");
    };
    const pagehide = () => controller.current.stop("pagehide");
    document.addEventListener("visibilitychange", visibility);
    window.addEventListener("pagehide", pagehide);
    return () => {
      alive.current = false;
      controller.current.dispose();
      document.removeEventListener("visibilitychange", visibility);
      window.removeEventListener("pagehide", pagehide);
      if (exported.current) URL.revokeObjectURL(exported.current);
    };
  }, []);
  const start = () => {
    if (!enabled || !supported) return;
    controller.current.start();
    onActivate();
  };
  const toggle = () => {
    const next = !enabled;
    setEnabled(next);
    try {
      localStorage.setItem(PREFERENCE, next ? "on" : "off");
    } catch {}
    if (!next) controller.current.stop("disabled");
    else if (supported) {
      controller.current.start();
      onActivate();
    }
  };
  const exportLogs = () => {
    if (exported.current) URL.revokeObjectURL(exported.current);
    const blob = new Blob(
      [
        JSON.stringify(
          {
            format: "synscore-voice-v1",
            exportedAt: new Date().toISOString(),
            userAgent: navigator.userAgent,
            language: "zh-TW",
            entries: entries.current,
          },
          null,
          2,
        ),
      ],
      { type: "application/json" },
    );
    exported.current = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = exported.current;
    a.download = `synscore-voice-${Date.now()}.json`;
    a.click();
  };
  return {
    enabled,
    supported,
    status,
    logs,
    toggle,
    start,
    listening: [
      "starting",
      "listening",
      "sending",
      "restarting",
      "standby",
    ].includes(status.phase),
    canStart: active && inPlay && !!available && supported,
    stop: () => controller.current.stop("manual-stop"),
    exportLogs,
    clearLogs: () => {
      entries.current = [];
      setLogs([]);
    },
  };
}
